begin

  -- hygiene intermediate final - ord 11
  select case when md5(prompt) = 'ab5b8b86c1e132aa72c90a9a06857ff1' and md5(coalesce(explanation, '')) = '5da5ffe26300a523ab59207623aa7fc6' and md5(options::text) = md5('["0.504766 h", "3.031433 h", "0.159621 h", "0.800000 h"]'::jsonb::text) and answer_index = 3 then 'old'
