              else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'hygiene' and tier = 'intermediate' and scope = 'final' and module_key is not distinct from null and ord = 11 and active;
  if v_state is null then raise exception 'roundoff bank hygiene refused: no row for hygiene intermediate final - ord 11'; end if;
  if v_state = 'other' then raise exception 'roundoff bank hygiene refused: hygiene intermediate final - ord 11 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'A 97.000000 dBA task is the only noise on a shift. After how long does the day reach LEX,8h 87?', options = '["0.504766 h", "3.031433 h", "0.159621 h", "0.800000 h"]'::jsonb,
